package main

import (
	"bytes"
	"compress/bzip2"
	"encoding/hex"
	"fmt"
	"hash/crc32"
	"io"
	"strings"
)

func L(b []byte) string {
	s := []string{}
	for _, x := range b {
		s = append(s, fmt.Sprint(x))
	}
	return "[" + strings.Join(s, ", ") + "]"
}

func run(b []byte) ([]byte, string) {
	out, err := io.ReadAll(bzip2.NewReader(bytes.NewReader(b)))
	if err != nil {
		return out, err.Error()
	}
	return out, ""
}

func H(s string) []byte {
	b, _ := hex.DecodeString(s)
	return b
}

func head(b []byte) []byte {
	if len(b) > 12 {
		return b[:12]
	}
	return b
}

